<script setup>
import { ref,onMounted,onBeforeUnmount } from 'vue';
import { useRouter } from 'vue-router';
import { api,setSession } from '../api/index.js';
const router=useRouter(),csrf=ref(''),passkey=ref(''),username=ref(''),token=ref(''),password=ref(''),confirmPassword=ref(''),error=ref(''),busy=ref(false);
onMounted(async()=>{try{csrf.value=(await api('/auth/recovery/context',{quiet:true})).csrfToken;}catch(e){error.value=e.message;}});
onBeforeUnmount(()=>{passkey.value=token.value=password.value=confirmPassword.value='';});
async function verify(){busy.value=true;error.value='';try{const result=await api('/auth/recovery/verify',{method:'POST',csrf:csrf.value,body:{passkey:passkey.value},quiet:true});username.value=result.username;token.value=result.token;passkey.value='';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function reset(){if(password.value!==confirmPassword.value){error.value='两次密码输入不一致';return;}busy.value=true;error.value='';try{await api('/auth/recovery/reset',{method:'POST',csrf:csrf.value,body:{token:token.value,password:password.value,confirmPassword:confirmPassword.value},quiet:true});setSession(null);await router.replace('/login');}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><main class="recovery-page"><section class="panel"><div class="panel-body"><h1>找回账号</h1><p class="muted">输入数据目录中 passkey 文件内的恢复密钥，验证后可查看用户名并设置新密码。</p><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon /><el-form label-position="top" :disabled="busy" @submit.prevent="token ? reset() : verify()"><template v-if="!token"><el-form-item label="恢复密钥"><el-input v-model="passkey" type="password" show-password aria-label="恢复密钥" autocomplete="off" /></el-form-item><el-button native-type="submit" type="primary" :disabled="!csrf || !passkey" :loading="busy">验证恢复密钥</el-button></template><template v-else><p>用户名：{{ username }}</p><p class="muted">请在 5 分钟内完成密码重置。</p><el-form-item label="新密码"><el-input v-model="password" type="password" show-password aria-label="新密码" autocomplete="new-password" maxlength="1024" /></el-form-item><el-form-item label="确认新密码"><el-input v-model="confirmPassword" type="password" show-password aria-label="确认新密码" autocomplete="new-password" maxlength="1024" /></el-form-item><el-button native-type="submit" type="primary" :disabled="password.length < 8 || !confirmPassword" :loading="busy">重置密码</el-button></template></el-form><p><router-link to="/login">返回登录</router-link></p></div></section></main></template>
<style scoped>.recovery-page{max-width:560px;margin:40px auto;padding:0 16px;}.el-alert{margin-bottom:20px;}</style>
